export function encodeCursor(task: { createdAt: Date; id: string }): string {
  const body = `${task.createdAt.toISOString()}|${task.id}`
  const mac = sign(body)
  return Buffer.from(`${body}|${mac}`).toString('base64url')
}

export function decodeCursor(cursor: string): Position {
  const raw = Buffer.from(cursor, 'base64url').toString('utf8')
  const [createdAt, id, mac] = raw.split('|')
  if (!createdAt || !id || !mac) throw new BadCursor('malformed')
  if (!safeEqual(mac, sign(`${createdAt}|${id}`))) {
    throw new BadCursor('not issued by this server')
  }
  const at = new Date(createdAt)
  if (Number.isNaN(at.getTime())) throw new BadCursor('bad time')
  return { createdAt: at, id }
}

export async function listTasks(teamId: string, opts: { after?: Position; limit: number }) {
  const { after, limit } = opts
  const rows = await db.task.findMany({
    where: {
      teamId,
      ...(after && {
        OR: [
          { createdAt: { lt: after.createdAt } },
          { createdAt: after.createdAt, id: { lt: after.id } },
        ],
      }),
    },
    orderBy: [{ createdAt: 'desc' }, { id: 'desc' }],
    take: limit + 1,
  })
  const page = rows.slice(0, limit)
  const next = rows.length > limit ? encodeCursor(page[page.length - 1]) : null
  return { tasks: page, nextCursor: next }
}
